import React, {memo} from 'react';
import type {ReactNode} from 'react';

import type {LabelProps} from '@gravity-ui/uikit';
import {Label, getConfig} from '@gravity-ui/uikit';

import {useLocalizedString} from '~/src/hooks/useLocalizedString';

import {defaultMessages} from '../i18n';

import type {TagOption} from './types';
import {getTagsValues} from './utils/getRemainingTagsOption';

export type TagsListProps<ValueType> = {
    maxTagCount?: number;
    renderTag?: (option: TagOption<ValueType>) => ReactNode;
    onDeselect: (value: ValueType) => void;
    canDeselect?: (value: ValueType) => boolean;
    values?: TagOption<ValueType>[];
    tagTheme?: LabelProps['theme'];
    tagSize?: LabelProps['size'];
    tagClassName?: string;
    disabled?: boolean;
};

export const TagsListInternal = <ValueType,>({
    values,
    maxTagCount = 0,
    renderTag,
    onDeselect,
    tagClassName,
    tagTheme,
    tagSize,
    disabled,
    canDeselect,
}: TagsListProps<ValueType>) => {
    const config = getConfig();
    const {t} = useLocalizedString(defaultMessages, config.lang);
    const {tags, remainingTagOption} = getTagsValues<ValueType>(values, maxTagCount);

    if (renderTag) {
        return (
            <>
                {tags.map(renderTag)}
                {remainingTagOption && renderTag(remainingTagOption as TagOption<ValueType>)}
            </>
        );
    }

    return (
        <>
            {tags.map(({value, content}) => (
                <Label
                    key={content}
                    className={tagClassName}
                    theme={tagTheme}
                    type={disabled || (canDeselect && !canDeselect(value)) ? 'default' : 'close'}
                    size={tagSize}
                    onCloseClick={() => onDeselect(value)}
                    closeButtonLabel={t('label-deselect')}
                >
                    {content}
                </Label>
            ))}
            {remainingTagOption && (
                <Label theme="normal" size="xs">
                    {remainingTagOption.content}
                </Label>
            )}
        </>
    );
};

export const TagsList = memo(TagsListInternal) as typeof TagsListInternal;
